def generer_excel_demande_edt(donnees_lignes, nom_enseignant=""):
    """
    Génère un fichier Excel à partir des données de demande.
    Retourne un BytesIO.
    """
    try:
        df = pd.DataFrame(donnees_lignes)
        ordre_cols = ['Enseignements', 'Code', 'Enseignants', 'Horaire', 'Jours', 'Lieu', 'Promotion']
        cols_presentes = [c for c in ordre_cols if c in df.columns]
        df = df[cols_presentes]

        excel_buffer = io.BytesIO()
        with pd.ExcelWriter(excel_buffer, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='Demande EDT', index=False)
        excel_buffer.seek(0)
        return excel_buffer

    except Exception as e:
        st.error(f"Erreur génération Excel : {e}")
        return None


def generer_excel_toutes_demandes_edt(demandes):
    """
    Génère un fichier Excel récapitulatif de toutes les demandes EDT,
    avec le statut de chaque demande et le détail des créneaux proposés.
    Retourne un BytesIO prêt pour st.download_button.
    """
    try:
        lignes_recap = []
        lignes_detail = []

        for demande in demandes or []:
            nom_ens = demande.get("enseignant_nom", "Inconnu")
            email_ens = demande.get("enseignant_email", "N/A")
            statut = demande.get("statut", "En attente")
            date_dem = demande.get("date_demande", "")
            demande_id = demande.get("id", "")

            fichier_data = demande.get("fichier_data", {})
            lignes = fichier_data.get("lignes", []) if isinstance(fichier_data, dict) else []
            if not isinstance(lignes, list):
                lignes = []

            promotions = []
            for ligne in lignes:
                if isinstance(ligne, dict):
                    promo = str(
                        ligne.get("Promotion", "")
                    ).strip()
                    if promo and promo not in promotions:
                        promotions.append(promo)

            lignes_recap.append({
                "ID demande": demande_id,
                "Enseignant": nom_ens,
                "Email": email_ens,
                "Date de la demande": date_dem,
                "Statut": statut,
                "Nombre de créneaux": len(lignes),
                "Promotion(s)": ", ".join(promotions),
            })

            for numero, ligne in enumerate(lignes, 1):
                if not isinstance(ligne, dict):
                    ligne = {"Donnée": str(ligne)}
                lignes_detail.append({
                    "ID demande": demande_id,
                    "Enseignant": nom_ens,
                    "Email": email_ens,
                    "Date de la demande": date_dem,
                    "Statut": statut,
                    "N° créneau": numero,
                    "Enseignements": ligne.get("Enseignements", ""),
                    "Code": ligne.get("Code", ""),
                    "Enseignants": ligne.get("Enseignants", ""),
                    "Horaire": ligne.get("Horaire", ""),
                    "Jours": ligne.get("Jours", ""),
                    "Lieu": ligne.get("Lieu", ""),
                    "Promotion": ligne.get("Promotion", ""),
                })

        df_recap = pd.DataFrame(lignes_recap, columns=[
            "ID demande", "Enseignant", "Email", "Date de la demande",
            "Statut", "Nombre de créneaux", "Promotion(s)"
        ])
        df_detail = pd.DataFrame(lignes_detail, columns=[
            "ID demande", "Enseignant", "Email", "Date de la demande",
            "Statut", "N° créneau", "Enseignements", "Code",
            "Enseignants", "Horaire", "Jours", "Lieu", "Promotion"
        ])

        # Une feuille statistique par enseignant est également créée.
        if not df_recap.empty:
            df_par_enseignant = (
                df_recap.groupby(["Enseignant", "Email"], dropna=False)
                .agg(
                    **{
                        "Nombre de demandes": ("ID demande", "count"),
                        "Demandes en attente": ("Statut", lambda x: int((x == "En attente").sum())),
                        "Demandes approuvées": ("Statut", lambda x: int((x == "Approuvée").sum())),
                        "Demandes rejetées": ("Statut", lambda x: int((x == "Rejetée").sum())),
                        "Total créneaux": ("Nombre de créneaux", "sum"),
                    }
                )
                .reset_index()
            )
        else:
            df_par_enseignant = pd.DataFrame(columns=[
                "Enseignant", "Email", "Nombre de demandes", "Demandes en attente",
                "Demandes approuvées", "Demandes rejetées", "Total créneaux"
            ])

        excel_buffer = io.BytesIO()
        with pd.ExcelWriter(excel_buffer, engine="openpyxl") as writer:
            df_recap.to_excel(writer, sheet_name="Toutes les demandes", index=False)
            df_par_enseignant.to_excel(writer, sheet_name="Par enseignant", index=False)
            df_detail.to_excel(writer, sheet_name="Détail des créneaux", index=False)

            from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
            from openpyxl.utils import get_column_letter

            header_fill = PatternFill(start_color="1E3A8A", end_color="1E3A8A", fill_type="solid")
            header_font = Font(color="FFFFFF", bold=True, size=11)
            thin = Side(style="thin", color="D1D5DB")
            border = Border(left=thin, right=thin, top=thin, bottom=thin)

            for ws in writer.book.worksheets:
                ws.freeze_panes = "A2"
                ws.auto_filter.ref = ws.dimensions
                for cell in ws[1]:
                    cell.fill = header_fill
                    cell.font = header_font
                    cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
                    cell.border = border
                for row in ws.iter_rows(min_row=2):
                    for cell in row:
                        cell.alignment = Alignment(vertical="top", wrap_text=True)
                        cell.border = border
                for col_cells in ws.columns:
                    max_len = 0
                    for cell in col_cells:
                        value = "" if cell.value is None else str(cell.value)
                        max_len = max(max_len, len(value))
                    ws.column_dimensions[get_column_letter(col_cells[0].column)].width = min(max(max_len + 2, 12), 45)

        excel_buffer.seek(0)
        return excel_buffer
    except Exception as e:
        st.error(f"Erreur génération Excel global des demandes : {e}")
        return None


def _charger_demandes_locales_fichier():
    """Charge les demandes EDT enregistrées en secours (échec Supabase)
    depuis le fichier JSON partagé sur le serveur (FICHIER_DEMANDES_LOCAL).

    CORRECTIF : contrairement à st.session_state.demandes_edt_local (qui
    n'existe que dans la session du navigateur de la personne qui a fait
    la demande), ce fichier est partagé par TOUTES les sessions de
    l'application — l'administrateur peut donc voir les demandes
    déposées par n'importe quel enseignant, même si l'enregistrement
    Supabase a échoué pour cette demande précise.
    """
    try:
        if os.path.exists(FICHIER_DEMANDES_LOCAL):
            with open(FICHIER_DEMANDES_LOCAL, "r", encoding="utf-8") as f:
                contenu = json.load(f)
            if isinstance(contenu, list):
                return contenu
    except Exception:
        pass
    return []


def _sauvegarder_demandes_locales_fichier(liste_demandes):
    """Enregistre la liste complète des demandes EDT de secours dans le
    fichier JSON partagé (voir _charger_demandes_locales_fichier)."""
    try:
        with open(FICHIER_DEMANDES_LOCAL, "w", encoding="utf-8") as f:
            json.dump(liste_demandes, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def _ajouter_demande_locale_fichier(enregistrement):
    """Ajoute une demande au fichier JSON partagé de secours et lui
    attribue un identifiant unique (préfixé « local- » pour la distinguer
    sans ambiguïté d'un identifiant Supabase lors des actions Approuver /
    Rejeter / Supprimer)."""
    demandes_existantes = _charger_demandes_locales_fichier()
    identifiant_unique = f"local-{int(time.time() * 1000)}-{len(demandes_existantes) + 1}"
    enregistrement = dict(enregistrement)
    enregistrement["id"] = identifiant_unique
    enregistrement["_source"] = "fichier_local"
    demandes_existantes.append(enregistrement)
    _sauvegarder_demandes_locales_fichier(demandes_existantes)
    return enregistrement


# ============================================================
# CORRECTIF — COMPTAGE DE LA CHARGE HORAIRE (Cours / TD / TP)
# ------------------------------------------------------------
# Règle demandée : dans une même cellule (même Jour + même Horaire)
# pour un enseignant donné :
#   - si CETTE cellule contient PLUSIEURS SÉANCES DE LA MÊME NATURE
#     (par exemple TP-G1 et TP-G2 au même horaire — même séance,
#     seulement dédoublée par sous-groupe), cette nature n'est
#     comptabilisée QU'UNE SEULE FOIS ;
#   - si CETTE cellule contient PLUSIEURS NATURES DIFFÉRENTES
#     (par exemple un Cours ET un TD au même horaire), c'est un
#     CHEVAUCHEMENT : un enseignant ne peut pas assurer deux types
#     d'enseignement en même temps. Seule la nature PRIORITAIRE est
#     comptabilisée (ordre : COURS > TD > TP) et un message d'erreur
#     de chevauchement est affiché (voir
#     `_detecter_chevauchements_natures` et
#     `_afficher_erreur_chevauchement_natures`).
# ============================================================
_PRIORITE_NATURES = ["COURS", "TD", "TP"]


def _compter_natures_par_cellule(df_type, colonnes_cellule):
    """Compte le nombre de séances de Cours / TD / TP pour un enseignant.

    Pour chaque cellule (colonnes identifiant le jour + l'horaire) :
      - plusieurs lignes de la MÊME nature = UNE seule séance ;
      - plusieurs natures DIFFÉRENTES (chevauchement) = seule la nature
        prioritaire est comptée (COURS > TD > TP).

    'df_type' doit contenir une colonne 'Type' (valeurs 'COURS', 'TD' ou
    'TP') ainsi que les colonnes indiquées dans 'colonnes_cellule'
    (typiquement ['Jours', 'Horaire'] ou ['j_norm', 'h_norm']).
    Retourne (nb_cours, nb_td, nb_tp)."""
    if df_type is None or df_type.empty:
        return 0, 0, 0
    if 'Type' not in df_type.columns or any(
        c not in df_type.columns for c in colonnes_cellule
    ):
        return 0, 0, 0

    nb_cours = 0
    nb_td = 0
    nb_tp = 0
    for _, groupe_cellule in df_type.groupby(colonnes_cellule):
        natures_presentes = set(groupe_cellule['Type'].dropna().unique())
        # Une seule nature comptée par cellule : la plus prioritaire.
        if "COURS" in natures_presentes:
            nb_cours += 1
        elif "TD" in natures_presentes:
            nb_td += 1
        elif "TP" in natures_presentes:
            nb_tp += 1
    return nb_cours, nb_td, nb_tp


def _detecter_chevauchements_natures(df_type, colonnes_cellule):
    """Retourne la liste des cellules (jour + horaire) où un même
    enseignant a plusieurs natures DIFFÉRENTES (ex. Cours + TD).

    Chaque élément est un dict :
      {'jour': ..., 'horaire': ..., 'natures': ['COURS', 'TD'],
       'enseignements': ['...', '...']}
    """
    resultat = []
    if df_type is None or df_type.empty:
        return resultat
    if 'Type' not in df_type.columns or any(
        c not in df_type.columns for c in colonnes_cellule
    ):
        return resultat

    for cle, groupe_cellule in df_type.groupby(colonnes_cellule):
        natures_presentes = set(groupe_cellule['Type'].dropna().unique())
        if len(natures_presentes) > 1:
            # Affichage lisible : colonnes brutes si disponibles
            if 'Jours' in groupe_cellule.columns:
                jour_aff = str(groupe_cellule['Jours'].iloc[0])
            else:
                jour_aff = str(groupe_cellule[colonnes_cellule[0]].iloc[0])
            if 'Horaire' in groupe_cellule.columns:
                horaire_aff = str(groupe_cellule['Horaire'].iloc[0])
            else:
                horaire_aff = str(groupe_cellule[colonnes_cellule[-1]].iloc[0])
            natures_triees = [n for n in _PRIORITE_NATURES if n in natures_presentes]
            if 'Enseignements' in groupe_cellule.columns:
                enseignements = [
                    str(e) for e in groupe_cellule['Enseignements'].dropna().unique()
                ]
            else:
                enseignements = []
            resultat.append({
                'jour': jour_aff,
                'horaire': horaire_aff,
                'natures': natures_triees,
                'enseignements': enseignements,
            })
    return resultat


def _afficher_erreur_chevauchement_natures(df_type, colonnes_cellule, nom_enseignant=""):
    """Affiche (st.error) un message de chevauchement pour chaque cellule
    où l'enseignant a plusieurs natures différentes en même temps.
    Retourne la liste des chevauchements détectés."""
    chevauchements = _detecter_chevauchements_natures(df_type, colonnes_cellule)
    if chevauchements:
        prefixe = f" pour {nom_enseignant}" if nom_enseignant else ""
        lignes = []
        for c in chevauchements:
            detail = " + ".join(c['natures'])
            ens_txt = f" ({' / '.join(c['enseignements'])})" if c['enseignements'] else ""
            lignes.append(
                f"- **{c['jour']} — {c['horaire']}** : {detail}{ens_txt}"
            )
        st.error(
            f"🚨 Chevauchement détecté{prefixe} : un enseignant ne peut pas "
            f"avoir deux types d'enseignement en même temps. Seule la nature "
            f"prioritaire (COURS > TD > TP) est comptabilisée pour ces créneaux.\n\n"
            + "\n".join(lignes)
        )
    return chevauchements


def sauvegarder_demande_edt(email_prof, nom_prof, donnees_lignes, supabase_client):

    """
    Sauvegarde une demande EDT. Si Supabase échoue, bascule en local.
    Garantit l'ordre des colonnes : Enseignements, Code, Enseignants, Horaire, Jours, Lieu, Promotion

    ------------------------------------------------------------------
    CORRECTIF — visibilité des demandes de secours :
    ------------------------------------------------------------------
    Auparavant, une demande dont l'enregistrement Supabase échouait était
    uniquement placée dans st.session_state.demandes_edt_local, une
    mémoire PROPRE à la session du navigateur de l'enseignant qui a
    déposé la demande. Résultat : l'administrateur (qui a sa propre
    session, sur son propre navigateur) ne pouvait JAMAIS la voir sur la
    plateforme, alors que l'email de notification, lui, partait bien
    (il ne dépend pas de Supabase). C'est exactement le symptôme
    rapporté : des demandes reçues « uniquement par email ».

    Cette demande de secours est désormais également enregistrée dans un
    fichier JSON partagé sur le serveur (FICHIER_DEMANDES_LOCAL), visible
    par TOUTES les sessions — y compris celle de l'administrateur.
    """
    try:
        # Utilise la fonction pro pour garantir l'ordre exact des colonnes
        excel_buffer = generer_excel_demande_edt(donnees_lignes, nom_prof)
        if excel_buffer is None:
            return False, "❌ Erreur lors de la génération Excel", None
        
        excel_buffer.seek(0)
        fichier_bytes = excel_buffer.getvalue()

        date_now = datetime.now()
        fichier_data = {
            "enseignant_email": email_prof,
            "enseignant_nom": nom_prof,
            "lignes": donnees_lignes,
            "date_generation": date_now.strftime("%d/%m/%Y %H:%M")
        }

        supabase_ok = False
        if supabase_client:
            try:
                supabase_client.table("edt_update_requests").insert({
                    "enseignant_id": email_prof,
                    "enseignant_email": email_prof,
                    "enseignant_nom": nom_prof,
                    "fichier_data": fichier_data,
                    "statut": "En attente",
                    "date_demande": date_now.isoformat()
                }).execute()
                supabase_ok = True
            except Exception as e:
                print(f"[SUPABASE] Erreur : {e}")

        if not supabase_ok:
            # --- Fichier JSON partagé (visible par toutes les sessions,
            #     y compris celle de l'administrateur) : SOURCE DE VÉRITÉ
            #     UNIQUE pour les demandes de secours (on ne duplique plus
            #     en st.session_state, afin d'éviter tout doublon d'affichage
            #     si jamais la même session consultait aussi la page admin). ---
            _ajouter_demande_locale_fichier({
                "enseignant_email": email_prof,
                "enseignant_nom": nom_prof,
                "fichier_data": fichier_data,
                "statut": "En attente",
                "date_demande": date_now.strftime("%d/%m/%Y %H:%M"),
            })

        demande_info = {
            "enseignant_nom": nom_prof,
            "enseignant_email": email_prof,
            "date_demande": date_now.strftime("%d/%m/%Y %H:%M"),
            "lignes": donnees_lignes
        }
        email_envoye = envoyer_email_notification_admin(demande_info, fichier_bytes)

        if supabase_ok:
            msg = "✅ Demande enregistrée en ligne."
        else:
            msg = "✅ Demande enregistrée (mode local — fichier partagé)."

        if email_envoye:
            msg += " 📧 Admin notifié."
        else:
            msg += " (Email non transmis.)"

        return True, msg, fichier_bytes

    except Exception as e:
        return False, f"❌ Erreur : {str(e)[:150]}", None
        

def generer_excel_demande_edt(donnees_lignes, nom_enseignant=""):
    """
    Génère un fichier Excel à partir des données de demande.
    Retourne un BytesIO prêt pour st.download_button
    """
    import io, pandas as pd
    from datetime import datetime
    
    try:
        df = pd.DataFrame(donnees_lignes)
        
        # Réordonner les colonnes pour un affichage pro
        ordre_cols = ['Enseignements', 'Code', 'Enseignants', 'Horaire', 'Jours', 'Lieu', 'Promotion']
        cols_presentes = [c for c in ordre_cols if c in df.columns]
        df = df[cols_presentes]
        
        excel_buffer = io.BytesIO()
        with pd.ExcelWriter(excel_buffer, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='Demande EDT', index=False)
            ws = writer.sheets['Demande EDT']
            
            # Mise en forme professionnelle
            from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
            header_fill = PatternFill(start_color="1E3A8A", end_color="1E3A8A", fill_type="solid")
            header_font = Font(color="FFFFFF", bold=True, size=11)
            thin_border = Border(
                left=Side(style='thin'), right=Side(style='thin'),
                top=Side(style='thin'), bottom=Side(style='thin')
            )
            
            for cell in ws[1]:
                cell.fill = header_fill
                cell.font = header_font
                cell.alignment = Alignment(horizontal='center', vertical='center')
                cell.border = thin_border
            
            # Ajustement auto des largeurs
            for column in ws.columns:
                max_length = 0
                column_letter = column[0].column_letter
                for cell in column:
                    try:
                        if cell.value:
                            max_length = max(max_length, len(str(cell.value)))
                    except:
                        pass
                ws.column_dimensions[column_letter].width = min(max_length + 4, 40)
        
        excel_buffer.seek(0)
        return excel_buffer
        
    except Exception as e:
        st.error(f"Erreur génération Excel : {e}")
        return None
