def _pdf_txt(val, val_defaut="N/A"):
    """Nettoie une valeur pour le PDF (None/NaN -> défaut, accents conservés)."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return val_defaut
    s = str(val).strip()
    if s == "" or s.lower() in ("nan", "none"):
        return val_defaut
    return s



