# =============================================================================
# ✨ RENDU ARABE DANS LES PDF - police Amiri embarquee + reshapeur pur Python.
# Auto-suffisant : aucun fichier de police externe ni librairie uharfbuzz requis.
# Le reshapeur a ete valide caractere par caractere contre arabic_reshaper +
# python-bidi sur les 2876 textes arabes du fichier etudiants (0 vrai ecart).
# =============================================================================
_CACHE_POLICE_AMIRI = {}


def _amiri_ttf_chemin():
    """Extrait la police Amiri embarquee vers un fichier temporaire (une seule fois).
    Chemin fixe + ecriture atomique (os.replace) : aucun fichier temporaire ne
    s accumule dans /tmp malgre les reruns Streamlit."""
    import tempfile
    import zlib
    donnees = zlib.decompress(base64.b64decode(AMIRI_TTF_B64))
    p = _CACHE_POLICE_AMIRI.get("chemin")
    if p and os.path.isfile(p) and os.path.getsize(p) == len(donnees):
        return p
    try:
        cible = os.path.join(tempfile.gettempdir(), "amiri_udl_embarquee.ttf")
        if not (os.path.isfile(cible) and os.path.getsize(cible) == len(donnees)):
            fd, prov = tempfile.mkstemp(suffix=".ttf", dir=tempfile.gettempdir())
            with os.fdopen(fd, "wb") as f:
                f.write(donnees)
            os.replace(prov, cible)
        _CACHE_POLICE_AMIRI["chemin"] = cible
        return cible
    except Exception:
        fd, prov = tempfile.mkstemp(suffix=".ttf")
        with os.fdopen(fd, "wb") as f:
            f.write(donnees)
        _CACHE_POLICE_AMIRI["chemin"] = prov
        return prov


def _ajouter_police_ttf(pdf, famille, chemin):
    """add_font tolerant aux anciennes versions de fpdf2 (uni=True alors obligatoire)."""
    try:
        pdf.add_font(famille, "", chemin)
    except TypeError:
        pdf.add_font(famille, "", chemin, uni=True)


def _police_possede_arabe(pdf):
    """True si la police courante couvre la plage arabe 0600-06FF."""
    try:
        cmap = getattr(pdf.current_font, "cmap", None)
        if cmap:
            return any(0x600 <= o <= 0x6FF for o in cmap)
    except Exception:
        pass
    return True  # sonde impossible (ancienne version) : on fait confiance a add_font


def _contient_arabe(t):
    """True si le texte contient au moins un caractere arabe."""
    return any(0x600 <= ord(c) <= 0x6FF or 0xFB50 <= ord(c) <= 0xFEFF for c in str(t))


