def normaliser_mat_etudiant(valeur):
    'Normalise un matricule pour permettre une correspondance fiable.'
    if valeur is None:
        return ""
    try:
        if pd.isna(valeur):
            return ""
    except Exception:
        pass
    s = str(valeur).strip()
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    s = re.sub(r"\s+", "", s)
    return s

def indexer_comptes_etudiants():
    'Construit un index {N° inscription: données du compte}.'
    index = {}
    for compte in COMPTES_ETUDIANTS_ETT:
        mat = normaliser_mat_etudiant(compte.get("N° inscription", ""))
        if mat:
            index[mat] = compte
    return index

COMPTES_ETUDIANTS_INDEX = indexer_comptes_etudiants()

