# FONCTION DE LECTURE EXCEL ROBUSTE
    # =============================================================================
def lire_excel_robuste(chemin_ou_fichier, sheet_name=0):
    """Lit un fichier Excel en essayant plusieurs engines (.xlsx, .xls, .xlsb)."""
    if chemin_ou_fichier is None:
        return None
    
    if hasattr(chemin_ou_fichier, 'seek'):
        chemin_ou_fichier.seek(0)
    
    # Détection prioritaire selon l'extension
    nom = ""
    if hasattr(chemin_ou_fichier, 'name'):
        nom = chemin_ou_fichier.name.lower()
    elif isinstance(chemin_ou_fichier, str):
        nom = os.path.basename(chemin_ou_fichier).lower()
    
    # Ordre des engines : xlrd prioritaire pour les .xls anciens
    engines = ['openpyxl', 'xlrd', 'pyxlsb']
    if nom.endswith('.xls') and not nom.endswith('.xlsx'):
        engines = ['xlrd', 'openpyxl', 'pyxlsb']
    
    last_err = None
    for engine in engines:
        try:
            if hasattr(chemin_ou_fichier, 'seek'):
                chemin_ou_fichier.seek(0)
            return pd.read_excel(chemin_ou_fichier, sheet_name=sheet_name, engine=engine)
        except Exception as e:
            last_err = e
            continue
            
    raise ValueError(f"❌ Format non reconnu. Utilisez un fichier Excel valide (.xlsx, .xls, .xlsb). Erreur : {last_err}")


# ============================================================
# GÉNÉRATEUR HTML « UNE SEULE PAGE » (AUTO-CONTENU)
# ============================================================
# Construit un fichier HTML complet (DOCTYPE + CSS inclus)
# formaté pour tenir sur UNE SEULE page A4 paysage à
# l'impression :
#   - @page : A4 paysage, marges réduites (8 mm) ;
#   - le contenu (en-tête ISO + grille) est placé dans un
#     conteneur de largeur fixe, réduit (zoom CSS) selon le
#     nombre de jours et de créneaux afin que TOUT tienne
#     sur une seule page ;
#   - print-color-adjust:exact conserve les couleurs à
#     l'impression (en-tête bleu, bordures de la grille).
# ============================================================
def _html_document_une_page(contenu_html, nb_jours=6, nb_creneaux=8,
                            titre="EMPLOI DU TEMPS"):
    # Dimensions imprimables A4 paysage (marges 8 mm), en pixels
    # CSS (≈ 96 dpi) : largeur ≈ 1063 px, hauteur ≈ 737 px.
    page_w_px = 1063.0
    page_h_px = 737.0
    # Estimation de la taille NATURELLE du contenu :
    #   - colonne « Horaire » ≈ 120 px, chaque jour ≈ 210 px ;
    #   - en-tête ISO ≈ 160 px, chaque créneau ≈ 92 px.
    largeur_naturelle = 120.0 + nb_jours * 210.0
    hauteur_naturelle = 160.0 + nb_creneaux * 92.0
    # Zoom = facteur le plus contraignant (jamais > 100 %).
    zoom = min(1.0, page_w_px / largeur_naturelle,
               page_h_px / hauteur_naturelle)
    zoom_pct = max(35, int(round(zoom * 100)))
    return f"""<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="utf-8">
<title>{titre}</title>
<style>
    @page {{ size: A4 landscape; margin: 8mm; }}
    * {{ box-sizing: border-box; }}
    html, body {{ margin: 0; padding: 0; }}
    body {{
        font-family: 'Segoe UI', Arial, sans-serif;
        color: #1e293b;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }}
    @media screen {{
        body {{ background: #f1f5f9; padding: 16px; }}
    }}
    #conteneur_edt_1page {{
        width: {int(largeur_naturelle)}px;
        margin: 0 auto;
        background: #ffffff;
        padding: 6px;
        zoom: {zoom_pct}%;
    }}
    #conteneur_edt_1page table {{
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
        page-break-inside: avoid;
    }}
    #conteneur_edt_1page th, #conteneur_edt_1page td {{
        word-wrap: break-word;
        overflow-wrap: break-word;
    }}
</style>
</head>
<body>
<div id="conteneur_edt_1page">
{contenu_html}
</div>
</body>
</html>"""


# ============================================================
# LIEUX NON OCCUPÉS : créneaux libres par jour et horaire
# ============================================================
# Helpers auto-contenus (aucune dépendance aux variables des
# portails) utilisés par la vue « 🟢 Lieux Non Occupés » :
#   - _lieux_parse_heure        : '9h30' -> 570 minutes
#   - _lieux_parse_intervalle   : '9h30 - 11h' -> (570, 660)
#   - _lieux_norm_creneau       : '8h - 9h30' == '8h-9h30'
#   - _lieux_eclater            : 'A08/G1' -> ['A08', 'G1']
#   - _lieux_occups             : set des (jour, créneau, lieu) occupés
#   - _lieux_tous               : liste triée des lieux distincts
#   - _lieux_libres             : dict (jour, créneau) -> lieux libres
#   - _lieux_libres_excel_bytes : classeur Excel (grille + détail
#                                 + synthèse par salle)
#   - _lieux_libres_pdf_bytes   : PDF grille (jours vertical,
#                                 horaires horizontal)
# ============================================================
def _lieux_parse_heure(txt):
    """Convertit '8h', '9h30', '9:30' en minutes depuis minuit (None si échec)."""
    if txt is None:
        return None
    s = str(txt).strip().lower()
    if not s:
        return None
    s = s.replace("h", ":").replace(";", ":")
    if ":" in s:
        h_str, m_str = s.split(":", 1)
    else:
        h_str, m_str = s, "0"
    try:
        h = int(h_str.strip() or "0")
        m = int(m_str.strip() or "0") if (m_str.strip() or "0").isdigit() else 0
    except (ValueError, TypeError):
        return None
    if not (0 <= h <= 23 and 0 <= m <= 59):
        return None
    return h * 60 + m


def _lieux_parse_intervalle(txt):
    """'9h30 - 11h' -> (570, 660) ; (None, None) si non parsable."""
    if txt is None:
        return None, None
    s = str(txt).strip()
    s = s.replace("–", "-").replace("—", "-").replace("à", "-")
    if "-" not in s:
        return None, None
    parties = [p for p in s.split("-") if p.strip()]
    if len(parties) < 2:
        return None, None
    debut = _lieux_parse_heure(parties[0])
    fin = _lieux_parse_heure(parties[-1])
    if debut is not None and fin is not None and fin > debut:
        return debut, fin
    return None, None


def _lieux_norm_creneau(txt):
    """Normalisation IDENTIQUE a normalize() des grilles EDT de l'app :
    une seance occupe une case si son libelle normalise correspond
    EXACTEMENT au libelle normalise du creneau/jour (h_norm / j_norm)."""
    if not txt or txt == "Non défini":
        return "vide"
    s = str(txt).strip().lower()
    s = s.replace(" ", "").replace("-", "").replace("–", "")
    s = s.replace(":00", "").replace("h00", "h")
    return s


_LIEUX_EXCLUS = {
    "", "/", "non défini", "non defini", "nan", "none",
    "a distance", "à distance", "nondefini",
}


def _lieux_eclater(valeur):
    """Éclate une valeur composite ('A08/G1', 'Labo / G1') en lieux atomiques.
    Les valeurs vides, '/', 'Non défini', 'A distance' sont exclues."""
    if valeur is None:
        return []
    brut = str(valeur).strip()
    if not brut:
        return []
    brut = brut.replace("/", ",").replace("+", ",").replace(";", ",")
    morceaux = [m.strip() for m in brut.split(",")]
    return [m for m in morceaux if m and m.lower() not in _LIEUX_EXCLUS]


def _lieux_occups(df, horaires_list, jours_list):
    """Ensemble des (jour, creneau_affiche, lieu) occupes.

    ------------------------------------------------------------------
    CORRECTIF — correspondance par CHEVAUCHEMENT HORAIRE REEL :
    ------------------------------------------------------------------
    Les differentes promotions de l'etablissement n'utilisent pas
    toujours EXACTEMENT le meme libelle pour designer le meme creneau
    (ou des creneaux qui se recouvrent dans le temps) : par exemple
    « 14h - 15h30 » pour l'une, « 14h - 15h » et « 15h - 16h » pour une
    autre. Une correspondance par simple EGALITE de libelle normalise
    ratait alors les occupations reelles des lieux des lors que le
    libelle exact utilise par la seance ne correspondait pas MOT POUR
    MOT au libelle du creneau affiche — un lieu apparaissait alors a
    tort comme « libre » alors qu'il etait reellement occupe pendant
    (une partie de) ce creneau, faussant le comptage des lieux non
    occupes dans un sens comme dans l'autre selon les creneaux.

    Desormais, une seance occupe un creneau affiche des que sa PLAGE
    HORAIRE REELLE (heure de debut / heure de fin, en minutes) CHEVAUCHE
    reellement celle du creneau affiche — quel que soit le libelle exact
    utilise par la promotion source pour designer cette seance. C'est le
    fonctionnement standard d'un planificateur de salles : une salle
    occupee de 14h a 15h30 est bien occupee — et donc indisponible —
    pendant le creneau « 14h - 15h » ET pendant le creneau « 15h - 16h ».

    Si l'horaire d'une seance n'est pas parsable (format inhabituel), on
    se rabat sur la correspondance par libelle normalise EXACT (ancien
    comportement), pour ne perdre aucune occupation.

    Les lieux composites (« A08/G1 ») restent eclates salle par salle.
    """
    normes_j = {_lieux_norm_creneau(j): j for j in jours_list}
    normes_h_exact = {_lieux_norm_creneau(h): h for h in horaires_list}
    bornes_h = {h: _lieux_parse_intervalle(h) for h in horaires_list}

    occupe = set()
    if df is None or not hasattr(df, "columns"):
        return occupe
    if ("Lieu" not in df.columns or "Jours" not in df.columns
            or "Horaire" not in df.columns):
        return occupe

    for _, r in df.iterrows():
        lieux = _lieux_eclater(r.get("Lieu"))
        if not lieux:
            continue
        j_aff = normes_j.get(_lieux_norm_creneau(r.get("Jours")))
        if j_aff is None:
            continue

        horaire_brut = r.get("Horaire")
        debut_r, fin_r = _lieux_parse_intervalle(horaire_brut)

        creneaux_touches = []
        if debut_r is not None and fin_r is not None:
            for h_aff, (d_c, f_c) in bornes_h.items():
                if d_c is None or f_c is None:
                    continue
                # Chevauchement strict de deux intervalles [debut_r, fin_r[
                # et [d_c, f_c[ : deux creneaux simplement adjacents (qui se
                # touchent sans se recouvrir) ne sont PAS consideres en
                # conflit.
                if debut_r < f_c and d_c < fin_r:
                    creneaux_touches.append(h_aff)
        if not creneaux_touches:
            # Repli : correspondance exacte par libelle normalise, pour
            # les horaires non parsables au format « debut - fin ».
            h_aff = normes_h_exact.get(_lieux_norm_creneau(horaire_brut))
            if h_aff is not None:
                creneaux_touches.append(h_aff)

        for h_aff in creneaux_touches:
            for l in lieux:
                occupe.add((j_aff, h_aff, l))
    return occupe



def _lieux_tous(df):
    """Liste triée des lieux atomiques distincts du fichier source."""
    tous = set()
    if df is None or not hasattr(df, "columns") or "Lieu" not in df.columns:
        return []
    for v in df["Lieu"].unique():
        for l in _lieux_eclater(v):
            tous.add(l)
    return sorted(tous)


def _lieux_libres(df, horaires_list, jours_list):
    """Retourne (occupes, libres, tous) :
    - occupes : set des (jour, créneau, lieu) occupés
    - libres  : dict (jour, créneau) -> liste triée des lieux libres
    - tous    : liste triée des lieux distincts."""
    tous = _lieux_tous(df)
    occupes = _lieux_occups(df, horaires_list, jours_list)
    libres = {}
    for j in jours_list:
        for h in horaires_list:
            pris = {l for (jj, hh, l) in occupes if jj == j and hh == h}
            libres[(j, h)] = sorted(set(tous) - pris)
    return occupes, libres, tous


# ============================================================
# CORRECTIF : correspondance FLEXIBLE des créneaux horaires et
# des jours, à partir des EDT RÉELLEMENT GÉNÉRÉS (colonnes
# « Horaire » et « Jours » du fichier source Data), et non plus
# d'une liste figée en dur.
# ------------------------------------------------------------
# Problème corrigé : la liste fixe d'horaires utilisée par les
# grilles EDT contient des libellés proches mais distincts (ex.
# « 14h - 15h » ET « 14h - 15h30 », « 15h - 16h » ET « 15h30 - 17h »).
# Si les données sources n'utilisent réellement que l'un des deux,
# l'autre devient une colonne « fantôme » toujours vide, donc
# toujours comptée comme « libre » pour TOUS les lieux — ce qui
# gonflait artificiellement le nombre de lieux non occupés.
# À l'inverse, un horaire utilisé dans les données mais absent de
# la liste figée était tout simplement ignoré par la correspondance
# (aucune occupation détectée pour ce créneau), ce qui gonflait
# également le nombre de lieux considérés comme libres.
#
# Les fonctions ci-dessous reconstruisent donc la liste des
# créneaux (et des jours) à utiliser pour la correspondance
# lieu / horaire / jour en ne conservant QUE ce qui est
# effectivement utilisé dans les EDT déjà générés (toutes
# promotions confondues, puisque df est le fichier source complet),
# tout en ajoutant automatiquement les créneaux/jours réellement
# utilisés mais absents de la liste de référence.
# ============================================================
def _lieux_creneau_key(txt):
    """Clé de tri chronologique d'un horaire (heure de début, heure de
    fin, libellé). Les libellés non parsables sont repoussés en fin de
    liste plutôt que d'être perdus."""
    debut, fin = _lieux_parse_intervalle(txt)
    if debut is None:
        return (10**9, 10**9, str(txt))
    return (debut, fin, str(txt))


def _lieux_horaires_dynamiques(df, horaires_reference):
    """Liste des créneaux horaires à utiliser pour la correspondance
    « Lieux Non Occupés », déterminée de façon FLEXIBLE à partir de la
    colonne « Horaire » du fichier source Data (donc selon les EDT déjà
    générés pour TOUTES les promotions).

    Cohérente avec _lieux_occups (correspondance par CHEVAUCHEMENT
    HORAIRE REEL, pas par égalité stricte de libellé) :
      - un horaire de la liste de référence n'est conservé que s'il est
        réellement utilisé, OU CHEVAUCHÉ dans le temps par au moins une
        séance des données sources (sinon c'est un créneau « fantôme »
        toujours vide, donc toujours compté comme libre pour tous les
        lieux, ce qui fausse le comptage) ;
      - un horaire présent dans les données dont la plage horaire ne
        chevauche AUCUN horaire de référence (un créneau réellement
        nouveau, par ex. un cours du soir) est ajouté automatiquement.
    Résultat trié chronologiquement (heure de début)."""
    if df is None or not hasattr(df, "columns") or "Horaire" not in df.columns:
        return list(horaires_reference)

    bornes_ref = {h: _lieux_parse_intervalle(h) for h in horaires_reference}
    normes_ref = {_lieux_norm_creneau(h): h for h in horaires_reference}

    valeurs_reelles = []
    for v in df["Horaire"].dropna().unique():
        v_norm = _lieux_norm_creneau(v)
        if v_norm == "vide":
            continue
        d_v, f_v = _lieux_parse_intervalle(v)
        valeurs_reelles.append((v_norm, str(v).strip(), d_v, f_v))

    if not valeurs_reelles:
        return list(horaires_reference)

    def _chevauche_ref(d_v, f_v, d_ref, f_ref):
        if None in (d_v, f_v, d_ref, f_ref):
            return False
        return d_v < f_ref and d_ref < f_v

    # 1) Créneaux de référence réellement utilisés (libellé identique)
    #    ou chevauchés (plage horaire différente mais qui se recoupe)
    #    par au moins une séance des données sources.
    conserves = []
    for h in horaires_reference:
        v_norm_h = _lieux_norm_creneau(h)
        d_h, f_h = bornes_ref[h]
        utilise = any(
            v_norm == v_norm_h or _chevauche_ref(d_v, f_v, d_h, f_h)
            for (v_norm, v_brut, d_v, f_v) in valeurs_reelles
        )
        if utilise:
            conserves.append(h)

    # 2) Horaires réellement présents dans les données mais dont la
    #    plage horaire ne chevauche AUCUN créneau de référence : ce
    #    sont de véritables nouveaux créneaux, à ajouter tels quels.
    for (v_norm, v_brut, d_v, f_v) in valeurs_reelles:
        if v_norm in normes_ref:
            continue
        if d_v is None:
            # Libellé non parsable : ajouté par précaution (repli), pour
            # ne perdre aucune occupation potentielle.
            if v_brut not in conserves:
                conserves.append(v_brut)
            continue
        chevauche_qqch = any(
            _chevauche_ref(d_v, f_v, bornes_ref[h][0], bornes_ref[h][1])
            for h in horaires_reference
        )
        if not chevauche_qqch and v_brut not in conserves:
            conserves.append(v_brut)

    if not conserves:
        return list(horaires_reference)

    return sorted(set(conserves), key=_lieux_creneau_key)



def _lieux_jours_dynamiques(df, jours_reference):
    """Liste des jours à utiliser pour la correspondance « Lieux Non
    Occupés », déterminée de façon FLEXIBLE à partir de la colonne
    « Jours » du fichier source Data (mêmes principes que
    _lieux_horaires_dynamiques). Les jours de référence réellement
    utilisés conservent leur ordre habituel ; tout jour présent dans les
    données mais absent de la liste de référence est ajouté à la suite."""
    if df is None or not hasattr(df, "columns") or "Jours" not in df.columns:
        return list(jours_reference)

    normes_ref = {_lieux_norm_creneau(j): j for j in jours_reference}
    jours_reels_norm = set()
    jours_reels_bruts = {}
    for v in df["Jours"].dropna().unique():
        v_norm = _lieux_norm_creneau(v)
        if v_norm == "vide":
            continue
        jours_reels_norm.add(v_norm)
        if v_norm not in normes_ref:
            jours_reels_bruts[v_norm] = str(v).strip()

    if not jours_reels_norm:
        return list(jours_reference)

    resultat = [normes_ref[n] for n in normes_ref if n in jours_reels_norm]
    nouveaux = sorted(jours_reels_bruts.values())
    return resultat + nouveaux


def _lieux_libres_excel_bytes(jours, horaires, cellules, detail, synthese,
                              titre, sous_titre):
    """Construit le classeur Excel des lieux non occupés (3 feuilles) :
    1. « Grille »   : jours en lignes × horaires en colonnes ;
    2. « Détail »   : une ligne par (jour, horaire, lieu libre) ;
    3. « Synthèse » : par lieu, créneaux libres / occupés.
    cellules : dict (jour, horaire) -> (texte, est_libre)
    detail   : liste de (jour, horaire, lieu)
    synthese : liste de (lieu, nb_libres, nb_occupés)
    Retourne les octets du fichier .xlsx."""
    import io as _io
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Border, Side, PatternFill, Font

    buf = _io.BytesIO()
    wb = Workbook()

    bordure = Border(left=Side(style="thin", color="94A3B8"),
                     right=Side(style="thin", color="94A3B8"),
                     top=Side(style="thin", color="94A3B8"),
                     bottom=Side(style="thin", color="94A3B8"))
    fond_titre = PatternFill("solid", fgColor="1E3A8A")
    police_titre = Font(bold=True, color="FFFFFF", size=11)
    fond_libre = PatternFill("solid", fgColor="DCFCE7")
    fond_occupe = PatternFill("solid", fgColor="FEE2E2")
    police_libre = Font(bold=True, color="166534", size=10)
    police_occupe = Font(bold=True, color="991B1B", size=10)
    centre = Alignment(horizontal="center", vertical="center", wrap_text=True)

    # ── Feuille 1 : Grille (jours en vertical, horaires en horizontal) ──
    ws = wb.active
    ws.title = "Grille"
    n_col = len(horaires) + 1
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=n_col)
    c = ws.cell(row=1, column=1, value=titre)
    c.font = Font(bold=True, size=13, color="1E3A8A")
    c.alignment = centre
    ws.row_dimensions[1].height = 24
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=n_col)
    c = ws.cell(row=2, column=1, value=sous_titre)
    c.font = Font(size=10, color="475569")
    c.alignment = centre
    ws.row_dimensions[2].height = 18
    ws.merge_cells(start_row=3, start_column=1, end_row=3, end_column=n_col)
    c = ws.cell(row=3, column=1,
                value="Jours en vertical (lignes) × Horaires en horizontal (colonnes)")
    c.font = Font(italic=True, size=9, color="64748B")
    c.alignment = centre

    # En-têtes (ligne 5)
    ws.cell(row=5, column=1, value="Jour / Horaire")
    for i_h, h in enumerate(horaires, start=2):
        ws.cell(row=5, column=i_h, value=h)
    for col in range(1, n_col + 1):
        cc = ws.cell(row=5, column=col)
        cc.fill = fond_titre
        cc.font = police_titre
        cc.alignment = centre
        cc.border = bordure
    ws.column_dimensions["A"].width = 14
    for i_h in range(2, n_col + 1):
        ws.column_dimensions[ws.cell(row=5, column=i_h).column_letter].width = 16

    for i_j, j in enumerate(jours, start=6):
        cj = ws.cell(row=i_j, column=1, value=j)
        cj.font = Font(bold=True, size=10)
        cj.alignment = centre
        cj.border = bordure
        cj.fill = PatternFill("solid", fgColor="E2E8F0")
        for i_h, h in enumerate(horaires, start=2):
            texte, est_libre = cellules.get((j, h), ("", True))
            cc = ws.cell(row=i_j, column=i_h, value=texte)
            cc.alignment = centre
            cc.border = bordure
            if est_libre:
                cc.fill = fond_libre
                cc.font = police_libre
            else:
                cc.fill = fond_occupe
                cc.font = police_occupe
        ws.row_dimensions[i_j].height = 22

    # ── Feuille 2 : Détail (une ligne par créneau libre) ──
    ws2 = wb.create_sheet("Détail")
    entetes2 = ["Jour", "Horaire", "Lieu non occupé"]
    for i_e, e in enumerate(entetes2, start=1):
        cc = ws2.cell(row=1, column=i_e, value=e)
        cc.fill = fond_titre
        cc.font = police_titre
        cc.alignment = centre
        cc.border = bordure
        ws2.column_dimensions[cc.column_letter].width = 22
    for i_l, (j, h, l) in enumerate(detail, start=2):
        for i_v, v in enumerate((j, h, l), start=1):
            cc = ws2.cell(row=i_l, column=i_v, value=v)
            cc.border = bordure
            cc.alignment = centre
        if i_l % 2 == 0:
            for i_v in range(1, 4):
                ws2.cell(row=i_l, column=i_v).fill = PatternFill(
                    "solid", fgColor="F8FAFC")
    ws2.freeze_panes = "A2"
    ws2.auto_filter.ref = f"A1:C{max(1, len(detail) + 1)}"

    # ── Feuille 3 : Synthèse par lieu ──
    ws3 = wb.create_sheet("Synthèse par salle")
    entetes3 = ["Lieu", "Créneaux libres", "Créneaux occupés",
                "Disponibilité (%)"]
    for i_e, e in enumerate(entetes3, start=1):
        cc = ws3.cell(row=1, column=i_e, value=e)
        cc.fill = fond_titre
        cc.font = police_titre
        cc.alignment = centre
        cc.border = bordure
    ws3.column_dimensions["A"].width = 26
    for col_l in ("B", "C", "D"):
        ws3.column_dimensions[col_l].width = 18
    for i_l, (l, nb_l, nb_o) in enumerate(synthese, start=2):
        total = nb_l + nb_o
        pct = round(100.0 * nb_l / total) if total else 0
        for i_v, v in enumerate((l, nb_l, nb_o, pct), start=1):
            cc = ws3.cell(row=i_l, column=i_v, value=v)
            cc.border = bordure
            cc.alignment = centre
    ws3.freeze_panes = "A2"
    ws3.auto_filter.ref = f"A1:D{max(1, len(synthese) + 1)}"

    wb.save(buf)
    return buf.getvalue()


def _lieux_libres_pdf_bytes(jours, horaires, cellules, titre, sous_titre,
                            salle=None):
    """PDF UNE PAGE (A4 paysage) : grille des lieux non occupés,
    JOURS EN VERTICAL (lignes) × HORAIRES EN HORIZONTAL (colonnes).
    cellules : dict (jour, horaire) -> (texte, est_libre) ;
    les cellules libres sont sur fond vert, les occupées sur fond rouge.
    Le contenu est enveloppé dans un KeepInFrame (mode shrink) afin que
    la grille tienne toujours sur UNE SEULE page."""
    import io as _io
    from reportlab.lib import colors
    from reportlab.platypus import (SimpleDocTemplate, Table, TableStyle,
                                    Paragraph, Spacer, KeepInFrame)
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.pagesizes import landscape, A4
    from reportlab.lib.units import mm

    buf = _io.BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=landscape(A4),
        rightMargin=10 * mm, leftMargin=10 * mm,
        topMargin=10 * mm, bottomMargin=10 * mm)
    styles = getSampleStyleSheet()
    st_titre = ParagraphStyle(
        "LieuxTitre", parent=styles["Heading1"], fontSize=14,
        textColor=colors.HexColor("#1e293b"), spaceAfter=4, alignment=1)
    st_iso = ParagraphStyle(
        "LieuxIso", parent=styles["Normal"], fontSize=9,
        textColor=colors.HexColor("#64748b"), spaceAfter=3, alignment=1)
    st_legende = ParagraphStyle(
        "LieuxLegende", parent=styles["Normal"], fontSize=8.5,
        textColor=colors.HexColor("#475569"), spaceBefore=4, alignment=1)
    st_head = ParagraphStyle(
        "LieuxHead", parent=styles["Normal"], fontSize=8, leading=10,
        alignment=1, textColor=colors.white)
    st_cell = ParagraphStyle(
        "LieuxCell", parent=styles["Normal"], fontSize=7.5, leading=9,
        alignment=1)

    if salle:
        legende = ("Grille : jours en vertical (lignes) × horaires en "
                   "horizontal (colonnes) — cellule verte = créneau LIBRE, "
                   "cellule rouge = créneau OCCUPÉ.")
    else:
        legende = ("Grille : jours en vertical (lignes) × horaires en "
                   "horizontal (colonnes) — chaque cellule indique le NOMBRE "
                   "de lieux non occupés pour ce jour et cet horaire.")

    donnees = [[Paragraph("<b>Jour / Horaire</b>", st_head)]]
    for h in horaires:
        donnees[0].append(Paragraph(f"<b>{h}</b>", st_head))
    cmds = [
        ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#334155")),
        ("BOX", (0, 0), (-1, -1), 1, colors.HexColor("#1e293b")),
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1E3A8A")),
        ("BACKGROUND", (0, 1), (0, -1), colors.HexColor("#e2e8f0")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
    ]
    for i_j, j in enumerate(jours, start=1):
        ligne = [Paragraph(f"<b>{j}</b>", st_cell)]
        for i_h, h in enumerate(horaires, start=1):
            texte, est_libre = cellules.get((j, h), ("", True))
            ligne.append(Paragraph(str(texte), st_cell))
            cmds.append((
                "BACKGROUND", (i_h, i_j), (i_h, i_j),
                colors.HexColor("#dcfce7" if est_libre else "#fee2e2")))
        donnees.append(ligne)

    largeur_utile = landscape(A4)[0] - 20 * mm
    col_jour = 22 * mm
    col_h = (largeur_utile - col_jour) / max(1, len(horaires))
    table = Table(donnees, colWidths=[col_jour] + [col_h] * len(horaires),
                  repeatRows=1)
    table.setStyle(TableStyle(cmds))

    elements = [
        Paragraph(titre, st_titre),
        Paragraph(sous_titre, st_iso),
        Spacer(1, 4 * mm),
        table,
        Paragraph(legende, st_legende),
    ]
    hauteur_utile = landscape(A4)[1] - 20 * mm
    cadre = KeepInFrame(maxWidth=largeur_utile, maxHeight=hauteur_utile,
                        content=elements, mode="shrink")
    doc.build([cadre])
    return buf.getvalue()


