    def normalize(s):
        if not s or s == "Non défini": 
            return "vide"
        s = str(s).strip().lower()
        s = s.replace(" ", "").replace("-", "").replace("–", "")
        s = s.replace(":00", "").replace("h00", "h")
        return s

