# ═════════════════════════════════════════════════════════════════════════════
# MODULE : GÉNÉRATION AUTOMATIQUE DES PV DES COMITÉS PÉDAGOGIQUES
# ═════════════════════════════════════════════════════════════════════════════

def _pv_clean(value, default=""):
    """Retourne une chaîne propre et exploitable dans l'interface/PV."""
    if value is None:
        return default
    try:
        if pd.isna(value):
            return default
    except Exception:
        pass
    s = str(value).strip()
    if s.lower() in {"nan", "none", "nat", "null", "<na>"}:
        return default
    return s


def _pv_normalize(value):
    """Normalisation souple pour les comparaisons de noms/matières/promotions."""
    import unicodedata
    s = _pv_clean(value).lower()
    s = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")
    s = re.sub(r"[^a-z0-9]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def _pv_col(df, candidats):
    """Trouve une colonne en privilégiant la correspondance normalisée."""
    if df is None or df.empty:
        return None
    normal = {_pv_normalize(c): c for c in df.columns}
    for candidat in candidats:
        if _pv_normalize(candidat) in normal:
            return normal[_pv_normalize(candidat)]
    for col in df.columns:
        nc = _pv_normalize(col)
        for candidat in candidats:
            if _pv_normalize(candidat) in nc or nc in _pv_normalize(candidat):
                return col
    return None


def _pv_promotions(df_source):
    """Liste des promotions disponibles dans l'EDT."""
    col = _pv_col(df_source, ["Promotion", "Promotions"])
    if not col:
        return []
    valeurs = []
    for v in df_source[col].dropna().tolist():
        s = _pv_clean(v)
        if s and s.lower() not in {"non defini", "non défini"}:
            valeurs.append(s)
    return sorted(set(valeurs), key=lambda x: _pv_normalize(x))


@st.cache_data(show_spinner=False, ttl=600)
def _pv_contacts_index(df_contacts):
    """Index rapide des contacts pour éviter les recherches ligne par ligne à chaque rerun."""
    if df_contacts is None or df_contacts.empty:
        return {}
    result = {}
    cols = {str(c).strip().upper(): c for c in df_contacts.columns}
    col_nom = cols.get("NOM")
    col_prenom = cols.get("PRÉNOM") or cols.get("PRENOM")
    col_email = cols.get("EMAIL") or cols.get("E-MAIL")
    col_tel = cols.get("N°/TEL") or cols.get("N° DE TÉLÉPHONE") or cols.get("TÉLÉPHONE") or cols.get("TELEPHONE")
    col_qual = cols.get("QUALITÉ")
    col_grade = cols.get("GRADE")
    for row in df_contacts.itertuples(index=False):
        d = row._asdict() if hasattr(row, "_asdict") else {}
        nom = _pv_clean(d.get(col_nom, "")) if col_nom else ""
        prenom = _pv_clean(d.get(col_prenom, "")) if col_prenom else ""
        complet = f"{nom} {prenom}".strip()
        if not complet:
            continue
        item = {
            "Nom": complet,
            "Email": _pv_clean(d.get(col_email, "")) if col_email else "",
            "Téléphone": _pv_clean(d.get(col_tel, "")) if col_tel else "",
            "Qualité": _pv_clean(d.get(col_qual, "")) if col_qual else "",
            "Grade": _pv_clean(d.get(col_grade, "")) if col_grade else "",
        }
        result[_pv_normalize(complet)] = item
        if nom:
            result.setdefault(_pv_normalize(nom), item)
    return result


@st.cache_data(show_spinner=False, ttl=600)
def _pv_matiere_charge_cached(df_source, df_contacts, promotion):
    """Version optimisée : filtre vectoriel + index de contacts, sans iterrows imbriqués."""
    if df_source is None or df_source.empty:
        return pd.DataFrame(columns=["Matière", "Chargé de matière", "Email", "Téléphone"])

    col_mat = _pv_col(df_source, ["Enseignements", "Enseignement", "Matière", "Module"])
    col_promo = _pv_col(df_source, ["Promotion", "Promotions"])
    col_ens = _pv_col(df_source, ["Enseignants", "Enseignant", "Chargé de matière", "Charge de matiere"])
    if not col_mat or not col_promo:
        return pd.DataFrame(columns=["Matière", "Chargé de matière", "Email", "Téléphone"])

    promo_norm = _pv_normalize(promotion)
    promo_values = df_source[col_promo].fillna("").astype(str).str.strip()
    mat_values = df_source[col_mat].fillna("").astype(str).str.strip()
    mask = promo_values.map(_pv_normalize).eq(promo_norm) & mat_values.ne("")
    df = df_source.loc[mask, [col_mat] + ([col_ens] if col_ens else [])].copy()
    if df.empty:
        return pd.DataFrame(columns=["Matière", "Chargé de matière", "Email", "Téléphone"])

    contacts_index = _pv_contacts_index(df_contacts)
    lignes = []
    ens_col = col_ens
    for matiere, groupe in df.groupby(col_mat, sort=True):
        enseignants = []
        vus = set()
        if ens_col:
            for v in groupe[ens_col].tolist():
                ens = _pv_clean(v)
                if ens and _pv_normalize(ens) not in vus:
                    vus.add(_pv_normalize(ens))
                    enseignants.append(ens)
        charge = " / ".join(enseignants)
        email = ""
        telephone = ""
        for ens in enseignants:
            candidats = [ens, nettoyer_nom_enseignant(ens), extraire_nom_famille(ens)]
            for candidat in candidats:
                item = contacts_index.get(_pv_normalize(candidat))
                if item:
                    email = item.get("Email", "")
                    telephone = item.get("Téléphone", "")
                    break
            if email or telephone:
                break
        lignes.append({
            "Matière": _pv_clean(matiere),
            "Chargé de matière": charge or "Non renseigné",
            "Email": email or "Non renseigné",
            "Téléphone": telephone or "Non renseigné",
        })
    return pd.DataFrame(lignes).sort_values("Matière", key=lambda s: s.map(_pv_normalize)).reset_index(drop=True)


def _pv_matiere_charge(df_source, df_contacts, promotion):
    return _pv_matiere_charge_cached(df_source, df_contacts, promotion)


@st.cache_data(show_spinner=False, ttl=600)
def _pv_enseignants_promotion_cached(df_source, df_contacts, promotion):
    """Liste optimisée des enseignants d'une promotion, avec recherche de contacts indexée."""
    if df_source is None or df_source.empty:
        return []
    col_promo = _pv_col(df_source, ["Promotion", "Promotions"])
    col_ens = _pv_col(df_source, ["Enseignants", "Enseignant", "Chargé de matière", "Charge de matiere"])
    if not col_promo or not col_ens:
        return []

    promo_norm = _pv_normalize(promotion)
    promo_values = df_source[col_promo].fillna("").astype(str).str.strip()
    df = df_source.loc[promo_values.map(_pv_normalize).eq(promo_norm), [col_ens]]
    if df.empty:
        return []

    noms_edt = []
    vus = set()
    for val in df[col_ens].tolist():
        s = _pv_clean(val)
        if not s:
            continue
        parts = re.split(r"\s*(?:/|;|\\|\s+et\s+)\s*", s, flags=re.IGNORECASE)
        for ens in (x.strip() for x in parts):
            if not ens:
                continue
            key = _pv_normalize(ens)
            if key not in vus:
                vus.add(key)
                noms_edt.append(ens)

    contacts_index = _pv_contacts_index(df_contacts)
    result = []
    used_contacts = set()
    for ens in noms_edt:
        trouve = None
        for candidat in (ens, nettoyer_nom_enseignant(ens), extraire_nom_famille(ens)):
            item = contacts_index.get(_pv_normalize(candidat))
            if item:
                # Évite de dupliquer un même contact si plusieurs écritures de son nom existent dans l'EDT.
                key = _pv_normalize(item.get("Nom", ""))
                if key not in used_contacts:
                    trouve = dict(item)
                    used_contacts.add(key)
                    break
        if trouve is None:
            trouve = {"Nom": ens, "Email": "", "Téléphone": "", "Qualité": "", "Grade": ""}
        result.append(trouve)
    return result


def _pv_enseignants_promotion(df_source, df_contacts, promotion):
    return _pv_enseignants_promotion_cached(df_source, df_contacts, promotion)


@st.cache_data(show_spinner=False, ttl=600)
def _pv_etudiants_promotion_cached(df_etudiants, promotion):
    """Filtre les étudiants avec cache pour éviter de retraiter tout le fichier à chaque interaction."""
    if df_etudiants is None or df_etudiants.empty:
        return pd.DataFrame()
    col_promo = _pv_col(df_etudiants, ["Promotion", "Promotions", "Promo", "Niveau", "Année"])
    if not col_promo:
        return pd.DataFrame()
    promo_norm = _pv_normalize(promotion)
    promo_values = df_etudiants[col_promo].fillna("").astype(str).str.strip()
    d = df_etudiants.loc[promo_values.map(_pv_normalize).eq(promo_norm)].copy()
    if d.empty:
        return d
    col_nom = _pv_col(d, ["Nom", "NOM", "Nom de famille"])
    col_prenom = _pv_col(d, ["Prénom", "PRENOM", "Prenom"])
    col_email = _pv_col(d, ["Email", "E-mail", "Mail", "Courriel", "Adresse mail"])
    if "Nom_Complet" not in d.columns:
        if col_nom and col_prenom:
            d["Nom_Complet"] = d[col_nom].fillna("").astype(str).map(_pv_clean) + " " + d[col_prenom].fillna("").astype(str).map(_pv_clean)
        elif col_nom:
            d["Nom_Complet"] = d[col_nom].fillna("").astype(str).map(_pv_clean)
        else:
            d["Nom_Complet"] = d.index.map(lambda x: f"Étudiant {x}")
    d["Nom_Complet"] = d["Nom_Complet"].map(_pv_clean)
    d["Email_PV"] = d[col_email].map(_pv_clean) if col_email else ""
    d = d[d["Nom_Complet"].ne("")].drop_duplicates(subset=["Nom_Complet"])
    return d.sort_values("Nom_Complet", key=lambda s: s.map(_pv_normalize)).reset_index(drop=True)


def _pv_etudiants_promotion(df_etudiants, promotion):
    return _pv_etudiants_promotion_cached(df_etudiants, promotion)

def _pv_email_valide(email):
    email = _pv_clean(email)
    return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email))


def _pv_envoyer_invitation_email(destinataires, objet, corps_html):
    """Envoie l'invitation aux enseignants de la promotion et au délégué choisi."""
    destinataires = sorted(set(e.strip() for e in destinataires if _pv_email_valide(e)))
    if not destinataires:
        return False, "Aucune adresse email valide n'a été trouvée."
    try:
        SMTP_SERVER = "smtp.gmail.com"
        SMTP_PORT = 587
        SMTP_USER = "chef.department.elt.fge@gmail.com"
        SMTP_PASS = "gkzs pdza yodb icvd"
        msg = MIMEMultipart("alternative")
        msg["Subject"] = objet
        msg["From"] = SMTP_USER
        msg["To"] = ", ".join(destinataires)
        msg.attach(MIMEText(corps_html, "html", "utf-8"))
        with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=30) as server:
            server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.send_message(msg)
        return True, f"Invitation envoyée à {len(destinataires)} destinataire(s)."
    except Exception as exc:
        return False, f"Échec de l'envoi de l'invitation : {exc}"


def _pv_teacher_directory(df_contacts):
    """Liste des membres potentiels du comité à partir du fichier contacts."""
    if df_contacts is None or df_contacts.empty:
        return []
    result=[]
    for _, row in df_contacts.iterrows():
        nom=_pv_clean(row.get("NOM", ""))
        prenom=_pv_clean(row.get("PRÉNOM", row.get("PRENOM", "")))
        complet=f"{nom} {prenom}".strip()
        if not complet:
            continue
        email=_pv_clean(row.get("Email", row.get("E-mail", "")))
        tel=_pv_clean(row.get("N°/TEL", row.get("N° de téléphone", row.get("Téléphone", row.get("Telephone", "")))))
        qualite=_pv_clean(row.get("Qualité", ""))
        grade=_pv_clean(row.get("Grade", ""))
        result.append({"Nom":complet, "Email":email, "Téléphone":tel, "Qualité":qualite, "Grade":grade})
    return result


def _pv_ajouter_point():
    st.session_state.pv_pedagogique_points = int(st.session_state.get("pv_pedagogique_points", 3)) + 1


def _pv_supprimer_point():
    n=int(st.session_state.get("pv_pedagogique_points", 3))
    if n > 1:
        st.session_state.pv_pedagogique_points = n - 1


def _pv_docx_set_cell_shading(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = tcPr.find(qn("w:shd"))
    if shd is None:
        shd = OxmlElement("w:shd")
        tcPr.append(shd)
    shd.set(qn("w:fill"), fill)


def _pv_docx_set_cell_text(cell, text, bold=False, size=10, color="000000", align=WD_ALIGN_PARAGRAPH.LEFT):
    cell.text = ""
    p = cell.paragraphs[0]
    p.alignment = align
    r = p.add_run(_pv_clean(text))
    r.bold = bold
    r.font.name = "Arial"
    r.font.size = Pt(size)
    r.font.color.rgb = __import__("docx").shared.RGBColor.from_string(color)


def _pv_docx_add_title(doc, text, size=15):
    p=doc.add_paragraph()
    p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=p.add_run(text)
    r.bold=True
    r.font.name="Arial"
    r.font.size=Pt(size)
    r.font.color.rgb=__import__("docx").shared.RGBColor.from_string("1E3A8A")
    return p


def _pv_generer_word(data):
    """Génère le PV complet au format DOCX."""
    if Document is None:
        raise RuntimeError("python-docx n'est pas installé. Ajoutez 'python-docx' dans requirements.txt.")

    doc=Document()
    section=doc.sections[0]
    section.top_margin=Inches(0.65)
    section.bottom_margin=Inches(0.65)
    section.left_margin=Inches(0.7)
    section.right_margin=Inches(0.7)

    styles=doc.styles
    for style_name in ["Normal"]:
        stl=styles[style_name]
        stl.font.name="Arial"
        stl.font.size=Pt(10.5)

    # En-tête institutionnel
    p=doc.add_paragraph()
    p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=p.add_run("RÉPUBLIQUE ALGÉRIENNE DÉMOCRATIQUE ET POPULAIRE")
    r.bold=True; r.font.name="Arial"; r.font.size=Pt(11)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=p.add_run("MINISTÈRE DE L'ENSEIGNEMENT SUPÉRIEUR ET DE LA RECHERCHE SCIENTIFIQUE")
    r.bold=True; r.font.name="Arial"; r.font.size=Pt(10)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=p.add_run("UNIVERSITÉ DJILLALI LIABÈS DE SIDI BEL ABBÈS")
    r.bold=True; r.font.name="Arial"; r.font.size=Pt(11)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=p.add_run("FACULTÉ DE GÉNIE ÉLECTRIQUE — DÉPARTEMENT D'ÉLECTROTECHNIQUE")
    r.bold=True; r.font.name="Arial"; r.font.size=Pt(10)

    doc.add_paragraph()
    _pv_docx_add_title(doc,"PROCÈS-VERBAL DU COMITÉ PÉDAGOGIQUE",15)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=p.add_run(f"Promotion : {data['promotion']} — {data['annee']} — {data['semestre']}")
    r.bold=True; r.font.name="Arial"; r.font.size=Pt(11)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.add_run(f"Date : {data['date']}    |    Heure : {data['heure']}    |    Lieu : {data['lieu']}").font.size=Pt(10)

    doc.add_paragraph()
    _pv_docx_add_title(doc,"1. OUVERTURE DE LA SÉANCE",12)
    p=doc.add_paragraph(data["ouverture"])
    p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY

    _pv_docx_add_title(doc,"2. LISTE DE PRÉSENCE",12)
    presents=data.get("presents",[])
    absents=data.get("absents",[])
    rows=max(len(presents),len(absents),1)+1
    table=doc.add_table(rows=rows, cols=3)
    table.style="Table Grid"
    headers=["N°","Membre du comité","État"]
    for j,h in enumerate(headers):
        _pv_docx_set_cell_text(table.cell(0,j),h,True,10,"FFFFFF",WD_ALIGN_PARAGRAPH.CENTER)
        _pv_docx_set_cell_shading(table.cell(0,j),"1E3A8A")
    all_members=[]
    for m in presents:
        all_members.append((m,"Présent"))
    for m in absents:
        all_members.append((m,"Absent"))
    if not all_members:
        all_members=[("Aucun membre renseigné","-")]
    for i,(m,state) in enumerate(all_members,1):
        _pv_docx_set_cell_text(table.cell(i,0),str(i),False,9,align=WD_ALIGN_PARAGRAPH.CENTER)
        _pv_docx_set_cell_text(table.cell(i,1),m.get("Nom",m) if isinstance(m,dict) else m,False,9)
        _pv_docx_set_cell_text(table.cell(i,2),state,True,9,align=WD_ALIGN_PARAGRAPH.CENTER)

    if absents:
        p=doc.add_paragraph()
        r=p.add_run("Absences signalées : "); r.bold=True
        p.add_run(", ".join([a.get("Nom",str(a)) if isinstance(a,dict) else str(a) for a in absents]))

    _pv_docx_add_title(doc,"3. ORDRE DU JOUR",12)
    for i,point in enumerate(data.get("ordre_du_jour",[]),1):
        p=doc.add_paragraph(style=None)
        p.paragraph_format.left_indent=Inches(0.15)
        r=p.add_run(f"{i}. ")
        r.bold=True
        p.add_run(point)

    _pv_docx_add_title(doc,"4. SUIVI DES ENSEIGNEMENTS ET ÉTAT D'AVANCEMENT",12)
    matieres=data.get("matieres",[])
    if matieres:
        table=doc.add_table(rows=1, cols=5)
        table.style="Table Grid"
        heads=["Matière","Chargé de matière","Email","Téléphone","État d'avancement"]
        for j,h in enumerate(heads):
            _pv_docx_set_cell_text(table.cell(0,j),h,True,8.5,"FFFFFF",WD_ALIGN_PARAGRAPH.CENTER)
            _pv_docx_set_cell_shading(table.cell(0,j),"1E3A8A")
        for item in matieres:
            cells=table.add_row().cells
            vals=[item.get("Matière",""),item.get("Chargé de matière",""),item.get("Email",""),item.get("Téléphone",""),item.get("Etat d'avancement","")]
            for j,v in enumerate(vals):
                _pv_docx_set_cell_text(cells[j],v,False,8.2,"000000",WD_ALIGN_PARAGRAPH.LEFT)

    _pv_docx_add_title(doc,"5. EXAMEN DES POINTS DE L'ORDRE DU JOUR",12)
    for i,item in enumerate(data.get("points_pv",[]),1):
        p=doc.add_paragraph()
        r=p.add_run(f"Point {i} — {item.get('titre','')}")
        r.bold=True; r.font.size=Pt(10.5)
        contenu=item.get("contenu","").strip()
        if contenu:
            p=doc.add_paragraph(contenu)
            p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
        else:
            p=doc.add_paragraph("Aucune observation renseignée pour ce point.")
            p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY

    _pv_docx_add_title(doc,"6. DÉCISIONS ET RECOMMANDATIONS",12)
    decisions=data.get("decisions","").strip()
    p=doc.add_paragraph(decisions or "Aucune décision particulière n'a été renseignée.")
    p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY

    _pv_docx_add_title(doc,"7. CLÔTURE DE LA SÉANCE",12)
    p=doc.add_paragraph(data.get("cloture","").strip() or "La séance est levée après épuisement de l'ordre du jour.")
    p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY

    doc.add_paragraph()
    table=doc.add_table(rows=2,cols=2)
    table.style="Table Grid"
    _pv_docx_set_cell_text(table.cell(0,0),"Le Président du Comité Pédagogique",True,10,"FFFFFF",WD_ALIGN_PARAGRAPH.CENTER)
    _pv_docx_set_cell_text(table.cell(0,1),"Le Secrétaire de séance",True,10,"FFFFFF",WD_ALIGN_PARAGRAPH.CENTER)
    _pv_docx_set_cell_shading(table.cell(0,0),"1E3A8A"); _pv_docx_set_cell_shading(table.cell(0,1),"1E3A8A")
    _pv_docx_set_cell_text(table.cell(1,0),data.get("president","")+"\n\nSignature :",False,10,align=WD_ALIGN_PARAGRAPH.CENTER)
    _pv_docx_set_cell_text(table.cell(1,1),data.get("secretaire","")+"\n\nSignature :",False,10,align=WD_ALIGN_PARAGRAPH.CENTER)

    # =====================================================================
    # EN-TÊTE / LOGO — logo de l'université en haut à gauche sur toutes les pages
    # =====================================================================
    header=section.header
    header.is_linked_to_previous=False
    header.paragraphs[0].text=""
    header_table=header.add_table(rows=1, cols=2, width=Inches(7.1))
    header_table.autofit=True

    # Supprimer les bordures du tableau d'en-tête pour conserver un rendu propre.
    for row in header_table.rows:
        for cell in row.cells:
            tcPr=cell._tc.get_or_add_tcPr()
            tcBorders=tcPr.first_child_found_in("w:tcBorders")
            if tcBorders is None:
                tcBorders=OxmlElement("w:tcBorders")
                tcPr.append(tcBorders)
            for edge in ("top","left","bottom","right","insideH","insideV"):
                tag=qn(f"w:{edge}")
                element=tcBorders.find(tag)
                if element is None:
                    element=OxmlElement(f"w:{edge}")
                    tcBorders.append(element)
                element.set(qn("w:val"),"nil")

    p_logo=header_table.cell(0,0).paragraphs[0]
    p_logo.alignment=WD_ALIGN_PARAGRAPH.LEFT
    logo_path=_BASE_DIR / "logo.PNG"
    if not logo_path.exists():
        logo_path=Path("logo.PNG")
    if logo_path.exists():
        run_logo=p_logo.add_run()
        run_logo.add_picture(str(logo_path), width=Inches(0.75))
    else:
        r_logo=p_logo.add_run("[LOGO]")
        r_logo.font.name="Arial"
        r_logo.font.size=Pt(7)
        r_logo.font.italic=True

    # La deuxième cellule reste vide afin de conserver le logo strictement à gauche.
    header_table.cell(0,1).paragraphs[0].text=""

    # =====================================================================
    # PIED DE PAGE STANDARD — Référence à gauche + pagination X pages à droite
    # =====================================================================
    footer=section.footer
    footer.is_linked_to_previous=False
    footer.paragraphs[0].text=""

    footer_table=footer.add_table(rows=1, cols=2, width=Inches(7.1))
    footer_table.autofit=False
    footer_table.columns[0].width=Inches(5.9)
    footer_table.columns[1].width=Inches(1.2)

    # Tableau de pied de page sans bordures.
    for row in footer_table.rows:
        for cell in row.cells:
            tcPr=cell._tc.get_or_add_tcPr()
            tcBorders=tcPr.first_child_found_in("w:tcBorders")
            if tcBorders is None:
                tcBorders=OxmlElement("w:tcBorders")
                tcPr.append(tcBorders)
            for edge in ("top","left","bottom","right","insideH","insideV"):
                tag=qn(f"w:{edge}")
                element=tcBorders.find(tag)
                if element is None:
                    element=OxmlElement(f"w:{edge}")
                    tcBorders.append(element)
                element.set(qn("w:val"),"nil")

    # Référence standard, présente sur toutes les pages.
    p_ref=footer_table.cell(0,0).paragraphs[0]
    p_ref.alignment=WD_ALIGN_PARAGRAPH.LEFT
    rr=p_ref.add_run("Réf : UDL-GEL-ER-006-2026")
    rr.font.name="Arial"
    rr.font.size=Pt(8)

    # Pagination dynamique Word : PAGE / NUMPAGES donne par exemple 1/5, 2/5...
    p_page=footer_table.cell(0,1).paragraphs[0]
    p_page.alignment=WD_ALIGN_PARAGRAPH.RIGHT

    run_page=p_page.add_run()
    run_page.font.name="Arial"
    run_page.font.size=Pt(8)
    fld_page_begin=OxmlElement("w:fldChar")
    fld_page_begin.set(qn("w:fldCharType"),"begin")
    instr_page=OxmlElement("w:instrText")
    instr_page.set(qn("xml:space"),"preserve")
    instr_page.text=" PAGE "
    fld_page_sep=OxmlElement("w:fldChar")
    fld_page_sep.set(qn("w:fldCharType"),"separate")
    fld_page_end=OxmlElement("w:fldChar")
    fld_page_end.set(qn("w:fldCharType"),"end")
    run_page._r.append(fld_page_begin)
    run_page._r.append(instr_page)
    run_page._r.append(fld_page_sep)
    run_page._r.append(fld_page_end)

    slash=p_page.add_run("/")
    slash.font.name="Arial"
    slash.font.size=Pt(8)

    run_total=p_page.add_run()
    run_total.font.name="Arial"
    run_total.font.size=Pt(8)
    fld_total_begin=OxmlElement("w:fldChar")
    fld_total_begin.set(qn("w:fldCharType"),"begin")
    instr_total=OxmlElement("w:instrText")
    instr_total.set(qn("xml:space"),"preserve")
    instr_total.text=" NUMPAGES "
    fld_total_sep=OxmlElement("w:fldChar")
    fld_total_sep.set(qn("w:fldCharType"),"separate")
    fld_total_end=OxmlElement("w:fldChar")
    fld_total_end.set(qn("w:fldCharType"),"end")
    run_total._r.append(fld_total_begin)
    run_total._r.append(instr_total)
    run_total._r.append(fld_total_sep)
    run_total._r.append(fld_total_end)

    buffer=io.BytesIO()
    doc.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


def run_pv_pedagogique():
    """Interface complète de préparation et génération automatique des PV."""
    st.markdown("<h1 class='main-title'>📝 Générateur automatique des PV des Comités Pédagogiques</h1>", unsafe_allow_html=True)
    st.info("Sélectionnez une promotion : les matières, leurs chargés de matière, leurs emails et téléphones sont récupérés automatiquement depuis l'EDT et le répertoire des enseignants.")

    # Récupération des sources déjà chargées par l'application.
    df_source = None
    if "df" in globals() and isinstance(df, pd.DataFrame) and not df.empty:
        df_source = df.copy()
    elif os.path.exists(FILE_EDT):
        try:
            df_source = pd.read_excel(FILE_EDT)
            df_source.columns=[str(c).strip() for c in df_source.columns]
        except Exception as exc:
            st.error(f"Impossible de charger l'EDT : {exc}")
            return

    contacts = df_contacts if isinstance(df_contacts,pd.DataFrame) else None
    if df_source is None or df_source.empty:
        st.error("❌ Le fichier EDT est indisponible ou vide.")
        return

    promotions=_pv_promotions(df_source)
    if not promotions:
        st.error("❌ Aucune promotion n'a été trouvée dans la colonne Promotion de l'EDT.")
        return

    # ------------------ Invitation à la réunion ------------------
    # Cette section est volontairement placée en premier : elle permet de choisir
    # immédiatement la promotion, la date, l'heure et le lieu de la réunion.
    # L'ordre du jour est ensuite récupéré depuis les champs saisis dans la section 2.
    st.markdown("## ✉️ Invitation à la réunion")
    st.caption("Choisissez d'abord la promotion, la date, l'horaire et le lieu. L'invitation sera adressée automatiquement aux enseignants de la promotion et au délégué étudiant sélectionné lorsque leurs adresses email sont disponibles. L'ordre du jour saisi dans la section 2 sera repris automatiquement dans le message.")

    c_inv1, c_inv2, c_inv3 = st.columns(3)
    with c_inv1:
        promotion = st.selectbox("🎓 Promotion concernée", promotions, key="pv_promotion")
    with c_inv2:
        date_pv = st.date_input("📆 Date de la réunion", value=datetime.now().date(), key="pv_date")
    with c_inv3:
        heure = st.text_input("🕒 Horaire de la réunion", value="09:00", key="pv_heure")

    lieu = st.text_input("🏢 Lieu de la réunion", value="Salle de réunion du Département d'Électrotechnique", key="pv_lieu")

    # Les étudiants proviennent du fichier étudiants déjà chargé par la plateforme.
    df_etudiants_pv = globals().get("df_etu", None)
    if not isinstance(df_etudiants_pv, pd.DataFrame) or df_etudiants_pv.empty:
        df_etudiants_pv = globals().get("df_etu_edt", None)
    etudiants_promo = _pv_etudiants_promotion(df_etudiants_pv, promotion)

    # Les enseignants et leurs emails sont limités strictement à la promotion choisie.
    enseignants_promo = _pv_enseignants_promotion(df_source, contacts, promotion)
    emails_enseignants = [m.get("Email", "") for m in enseignants_promo if _pv_email_valide(m.get("Email", ""))]

    if not etudiants_promo.empty:
        noms_etudiants = etudiants_promo["Nom_Complet"].tolist()
        st.session_state["pv_delegue"] = st.session_state.get("pv_delegue", "")
        if st.session_state["pv_delegue"] not in noms_etudiants:
            st.session_state["pv_delegue"] = noms_etudiants[0]
        delegue = st.selectbox("🎓 Délégué de la promotion à inviter", noms_etudiants, key="pv_delegue")
        row_delegue = etudiants_promo[etudiants_promo["Nom_Complet"] == delegue].iloc[0]
        email_delegue = _pv_clean(row_delegue.get("Email_PV", ""))
        if email_delegue:
            st.caption(f"📧 Email du délégué : {email_delegue}")
        else:
            try:
                email_delegue = _pv_clean(trouver_email_étudiant(delegue, df_etudiants_pv))
            except Exception:
                email_delegue = ""
            if email_delegue:
                st.caption(f"📧 Email du délégué : {email_delegue}")
            else:
                st.warning("⚠️ Aucun email valide n'est disponible pour cet étudiant. Les enseignants pourront néanmoins recevoir l'invitation.")
    else:
        delegue = ""
        email_delegue = ""
        st.warning(f"⚠️ Aucun étudiant n'a été trouvé dans la promotion **{promotion}**.")

    st.write(f"📨 **Destinataires enseignants trouvés : {len(emails_enseignants)}** / {len(enseignants_promo)}")
    if emails_enseignants:
        with st.expander("👨‍🏫 Enseignants qui recevront l'invitation", expanded=False):
            for m in enseignants_promo:
                email_m = _pv_clean(m.get("Email", ""))
                if _pv_email_valide(email_m):
                    st.write(f"• {m.get('Nom','')} — {email_m}")
                else:
                    st.write(f"• {m.get('Nom','')} — ⚠️ email non renseigné")

    # L'ordre du jour est saisi plus bas. On lit ici les valeurs déjà présentes
    # dans session_state afin que le bouton d'envoi, placé en tête de page,
    # puisse reprendre automatiquement les points saisis dans la section 2.
    nb_points_invitation = int(st.session_state.get("pv_pedagogique_points", 3))
    ordre_non_vides_invitation = []
    for i in range(1, nb_points_invitation + 1):
        valeur = _pv_clean(st.session_state.get(f"pv_ordre_{i}", ""))
        if valeur:
            ordre_non_vides_invitation.append(valeur)

    if ordre_non_vides_invitation:
        with st.expander("📋 Ordre du jour actuellement enregistré pour l'invitation", expanded=False):
            for i, point in enumerate(ordre_non_vides_invitation, 1):
                st.write(f"{i}. {point}")
    else:
        st.info("ℹ️ L'ordre du jour sera repris automatiquement après sa saisie dans la section 2. Vous pouvez préparer l'invitation maintenant, puis l'envoyer après avoir renseigné l'ordre du jour.")

    if st.button("✉️ ENVOYER L'INVITATION DE RÉUNION", use_container_width=True, key="pv_send_invitation"):
        destinataires = list(emails_enseignants)
        if _pv_email_valide(email_delegue):
            destinataires.append(email_delegue)
        if not destinataires:
            st.error("❌ Aucun destinataire ne possède une adresse email valide.")
        else:
            ordre_html = "".join(f"<li>{x}</li>" for x in ordre_non_vides_invitation) or "<li>Ordre du jour à compléter</li>"
            objet = f"Invitation — Comité pédagogique {promotion} — {date_pv.strftime('%d/%m/%Y')}"
            corps_html = f"""<!DOCTYPE html>
<html lang='fr'><head><meta charset='UTF-8'></head>
<body style='font-family:Arial,sans-serif;color:#1e293b;line-height:1.6;'>
<h2 style='color:#1e3a8a;'>📋 Invitation au Comité Pédagogique</h2>
<p>Madame, Monsieur,</p>
<p>Vous êtes cordialement invité(e) à participer à la réunion du <strong>Comité Pédagogique</strong> de la promotion <strong>{promotion}</strong>.</p>
<table style='border-collapse:collapse;width:100%;max-width:700px;'>
<tr><td style='padding:7px;border:1px solid #ddd;'><strong>Date</strong></td><td style='padding:7px;border:1px solid #ddd;'>{date_pv.strftime('%d/%m/%Y')}</td></tr>
<tr><td style='padding:7px;border:1px solid #ddd;'><strong>Heure</strong></td><td style='padding:7px;border:1px solid #ddd;'>{heure}</td></tr>
<tr><td style='padding:7px;border:1px solid #ddd;'><strong>Lieu</strong></td><td style='padding:7px;border:1px solid #ddd;'>{lieu}</td></tr>
<tr><td style='padding:7px;border:1px solid #ddd;'><strong>Délégué étudiant</strong></td><td style='padding:7px;border:1px solid #ddd;'>{delegue or 'Non sélectionné'}</td></tr>
</table>
<h3 style='color:#1e3a8a;'>📋 Ordre du jour</h3>
<ol>{ordre_html}</ol>
<p>Votre présence et votre participation sont souhaitées afin d'examiner les questions pédagogiques relatives à la promotion.</p>
<p>Cordialement,<br><strong>Département d'Électrotechnique — FGE/UDL-SBA</strong></p>
</body></html>"""
            ok, message = _pv_envoyer_invitation_email(destinataires, objet, corps_html)
            if ok:
                st.success("✅ " + message)
                st.info("📧 Destinataires : " + ", ".join(destinataires))
            else:
                st.error("❌ " + message)

    # ------------------ Informations générales ------------------
    st.markdown("## 🏛️ 1. Informations générales du comité")
    c1,c2,c3=st.columns(3)
    with c1:
        st.markdown(f"**🎓 Promotion :** {promotion}")
        annee=st.text_input("📅 Année universitaire",value="2026-2027",key="pv_annee")
    with c2:
        semestre=st.selectbox("📚 Semestre",["Semestre 1","Semestre 2","Semestre 3"],key="pv_semestre")
        st.markdown(f"**📆 Date de la réunion :** {date_pv.strftime('%d/%m/%Y')}")
    with c3:
        st.markdown(f"**🕒 Heure :** {heure}")
        st.markdown(f"**🏢 Lieu :** {lieu}")

    matieres_df=_pv_matiere_charge(df_source,contacts,promotion)
    st.success(f"✅ {len(matieres_df)} matière(s) trouvée(s) pour la promotion **{promotion}**.")

    # ------------------ Ordre du jour ------------------
    st.markdown("## 📋 2. Ordre du jour")
    st.caption("Au départ, plusieurs champs sont ouverts. Ajoutez ou supprimez des points selon vos besoins.")
    nb_points=int(st.session_state.get("pv_pedagogique_points",3))
    ordre=[]
    for i in range(1,nb_points+1):
        val=st.text_input(f"Point {i} de l'ordre du jour",key=f"pv_ordre_{i}",placeholder=f"Ex. Point {i} — ...")
        ordre.append(val.strip())
    ca,cb=st.columns(2)
    with ca:
        st.button("➕ Ajouter un point",key="pv_add_point",on_click=_pv_ajouter_point,use_container_width=True)
    with cb:
        st.button("➖ Supprimer le dernier point",key="pv_del_point",on_click=_pv_supprimer_point,use_container_width=True)

    ordre_non_vides=[x for x in ordre if x]

    # ------------------ Présence ------------------
    st.markdown("## 👥 3. Liste de présence et des absents")
    # IMPORTANT : la liste est construite à partir de l'EDT de la promotion sélectionnée.
    # Ainsi, plusieurs enseignants peuvent apparaître et aucun enseignant d'une autre promotion
    # n'est proposé dans les listes de présence/absence.
    enseignants_promo = _pv_enseignants_promotion(df_source, contacts, promotion)
    membres = enseignants_promo
    noms_membres = [m["Nom"] for m in membres if _pv_clean(m.get("Nom", ""))]
    if not noms_membres:
        st.warning(f"⚠️ Aucun enseignant intervenant dans la promotion **{promotion}** n'a été trouvé dans l'EDT.")
        noms_membres=["Président du comité", "Secrétaire de séance"]

    # Nettoyage des anciennes sélections lorsque la promotion change : évite les erreurs
    # StreamlitDefaultNotInOptionsError avec des options devenues invalides.
    st.session_state["pv_presents"] = [x for x in st.session_state.get("pv_presents", []) if x in noms_membres]
    st.session_state["pv_absents"] = [x for x in st.session_state.get("pv_absents", []) if x in noms_membres]
    if st.session_state.get("pv_president") not in noms_membres:
        st.session_state["pv_president"] = noms_membres[0]
    if st.session_state.get("pv_secretaire") not in noms_membres:
        st.session_state["pv_secretaire"] = noms_membres[0]

    selection_presence=st.multiselect("👥 Membres présents",noms_membres,key="pv_presents")
    selection_absence=st.multiselect("🚫 Membres absents",[n for n in noms_membres if n not in selection_presence],key="pv_absents")
    c1,c2=st.columns(2)
    with c1:
        president=st.selectbox("👤 Président du comité",noms_membres,key="pv_president")
    with c2:
        secretaire=st.selectbox("🖊️ Secrétaire de séance",noms_membres,key="pv_secretaire")

    # ------------------ Etat d'avancement des matières ------------------
    st.markdown("## 📚 4. État d'avancement des matières")
    st.caption("Cliquez sur une matière : son champ de saisie s'ouvre pour renseigner l'état d'avancement qui sera repris automatiquement dans le PV Word.")

    if "pv_matieres_selectionnees" not in st.session_state:
        st.session_state.pv_matieres_selectionnees=[]

    options_matieres=matieres_df["Matière"].tolist() if not matieres_df.empty else []
    # IMPORTANT : après changement de promotion, certaines matières de l'ancienne
    # promotion peuvent ne plus exister dans les nouvelles options. On conserve
    # uniquement les valeurs encore valides avant d'appeler st.multiselect().
    options_matieres_set=set(options_matieres)
    st.session_state["pv_matieres_selectionnees"] = [
        x for x in st.session_state.get("pv_matieres_selectionnees", [])
        if x in options_matieres_set
    ]
    selected_matieres=st.multiselect(
        "📘 Sélectionner les matières à traiter dans le PV",
        options_matieres,
        default=st.session_state["pv_matieres_selectionnees"],
        key="pv_matieres_selectionnees"
    )

    matieres_pv=[]
    if selected_matieres:
        for idx,matiere in enumerate(selected_matieres,1):
            row=matieres_df[matieres_df["Matière"]==matiere].iloc[0].to_dict()
            with st.expander(f"📘 {idx}. {matiere} — {row.get('Chargé de matière','')}",expanded=True):
                c1,c2=st.columns(2)
                with c1:
                    st.markdown(f"**Chargé de matière :** {row.get('Chargé de matière','Non renseigné')}")
                    st.markdown(f"**Email :** {row.get('Email','Non renseigné')}")
                with c2:
                    st.markdown(f"**Téléphone :** {row.get('Téléphone','Non renseigné')}")
                etat=st.text_area("✍️ État d'avancement de cette matière",key=f"pv_etat_{_pv_normalize(matiere)}",height=130,placeholder="Décrire les chapitres réalisés, en cours, le taux d'avancement, les difficultés, les séances restantes, etc.")
                row["Etat d'avancement"]=etat.strip()
                matieres_pv.append(row)
    else:
        st.warning("Sélectionnez au moins une matière pour renseigner son état d'avancement.")

    # ------------------ Rédaction du PV par point ------------------
    st.markdown("## 🖊️ 5. Rédaction de chaque point du PV")
    st.caption("Chaque point de l'ordre du jour dispose de son propre champ. Le contenu sera repris tel quel dans le document Word.")
    points_pv=[]
    for i,titre in enumerate(ordre_non_vides,1):
        contenu=st.text_area(f"Point {i} — {titre}",key=f"pv_contenu_{i}",height=180,placeholder="Rédiger les échanges, constats, propositions, décisions et recommandations relatifs à ce point...")
        points_pv.append({"titre":titre,"contenu":contenu.strip()})

    # ------------------ Ouverture / décisions / clôture ------------------
    st.markdown("## 📝 6. Ouverture, décisions et clôture")
    ouverture=st.text_area("Texte d'ouverture de la séance",value=f"La séance du comité pédagogique de la promotion {promotion} est ouverte à {heure} sous la présidence de {president}. Les membres présents et absents sont consignés dans la présente liste. L'ordre du jour est soumis à l'examen du comité.",height=110,key="pv_ouverture")
    decisions=st.text_area("Décisions et recommandations générales",height=150,key="pv_decisions",placeholder="Synthèse des décisions arrêtées par le comité...")
    cloture=st.text_area("Texte de clôture",value="Après épuisement de l'ordre du jour, les travaux du comité pédagogique sont clôturés. Le présent procès-verbal est établi pour servir et valoir ce que de droit.",height=100,key="pv_cloture")

    # ------------------ Aperçu ------------------
    st.markdown("## 👁️ 7. Vérification avant génération")
    st.dataframe(matieres_pv if matieres_pv else matieres_df.head(0),use_container_width=True,hide_index=True)
    st.write(f"**Promotion :** {promotion}  |  **Matières sélectionnées :** {len(matieres_pv)}  |  **Présents :** {len(selection_presence)}  |  **Absents :** {len(selection_absence)}  |  **Points :** {len(points_pv)}")

    st.markdown("## 📄 8. Génération du PV Word")
    if st.button("📝 GÉNÉRER LE PV COMPLET EN WORD",type="primary",use_container_width=True,key="pv_generate_word"):
        if not ordre_non_vides:
            st.error("❌ Ajoutez au moins un point à l'ordre du jour.")
            return
        if not selected_matieres:
            st.error("❌ Sélectionnez au moins une matière et renseignez son état d'avancement.")
            return
        if not any(x.get("contenu") for x in points_pv):
            st.warning("⚠️ Aucun contenu n'a été renseigné dans les points du PV. Le document sera généré avec des rubriques à compléter.")

        data={
            "promotion":promotion,
            "annee":annee,
            "semestre":semestre,
            "date":date_pv.strftime("%d/%m/%Y"),
            "heure":heure,
            "lieu":lieu,
            "ouverture":ouverture,
            "presents":[next((m for m in membres if m["Nom"]==n),{"Nom":n}) for n in selection_presence],
            "absents":[next((m for m in membres if m["Nom"]==n),{"Nom":n}) for n in selection_absence],
            "ordre_du_jour":ordre_non_vides,
            "matieres":matieres_pv,
            "points_pv":points_pv,
            "decisions":decisions,
            "cloture":cloture,
            "president":president,
            "secretaire":secretaire,
        }
        try:
            word_bytes=_pv_generer_word(data)
            nom_fichier=f"PV_Comite_Pedagogique_{promotion.replace('/','-').replace(' ','_')}_{date_pv.strftime('%Y%m%d')}.docx"
            st.success("✅ PV Word généré avec succès.")
            st.download_button("📥 Télécharger le PV Word",data=word_bytes,file_name=nom_fichier,mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",use_container_width=True,key="pv_download_word")
        except Exception as exc:
            st.error(f"❌ Erreur lors de la génération du Word : {exc}")


