                                        masque_suppr = df_master['Promotion'] == str(current_promo).strip()
                                        lignes_supprimees = int(masque_suppr.sum())
                                        
                                        if lignes_supprimees > 0:
                                            df_master = df_master[~masque_suppr].copy()
